count = 0
for s in open('9-183.csv'):
    a = sorted(int(x) for x in s.split(';'))
    if a[2] < a[0] + a[1]:
        p = sum(a) / 2
        area2 = p * (p - a[0]) * (p - a[1]) * (p - a[2])
        if area2 >= 0:
            s = area2 ** 0.5
            if abs(s - round(s)) < 1e-9:
                count += 1
print(count)

