def f(x, y):
    if x == y:
        return 1
    if x > y:
        return 0
    return f(x + 1, y) + f(x * 2, y)

print(f(1, 16))

def f(x, y, s=''):
    if x == y:
        return int(len(s) >= 2 and s[-2] == '1')
    if x > y:
        return 0
    return f(x + 1, y, s + '1') + f(x * 2, y, s + '2')

print(f(3, 20))

from functools import lru_cache

@lru_cache(None)
def ways(cur, seen16):
    if cur == 21:
        return 0
    if cur > 60:
        return 0
    if cur == 60:
        return 1 if seen16 else 0
    total = ways(cur + 1, seen16 or cur + 1 == 16)
    total += ways(cur * 3, seen16 or cur * 3 == 16)
    total += ways(cur * 4, seen16 or cur * 4 == 16)
    return total

print(ways(2, False))

from functools import lru_cache

@lru_cache(None)
def f(pos, steps):
    if pos == 13:
        return 0
    if steps == 0:
        return 1 if pos == 15 else 0
    return f(pos + 1, steps - 1) + f(pos + 4, steps - 1)

print(f(1, 5))

from functools import lru_cache

@lru_cache(None)
def f(now):
    if now % 3 == 0:
        return 0
    if now == 100:
        return 1
    if now > 110:
        return 0
    return f(now - 1) + f(now + 3) + f(now * 2)

print(f(5))

