def divisors(x):
    ds = [1, x]
    d = 2
    while d * d <= x:
        if x % d == 0:
            ds.append(d)
            if x // d > d:
                ds.append(x // d)
        d += 1
    return sorted(ds)

best = []
for x in range(start, end + 1):
    ds = divisors(x)
    if len(ds) > len(best):
        best = ds

